class Solution:
    def maximumBeauty(self, flowers, newFlowers, target, full, partial):
        flowers.sort()
        n = len(flowers)
        pre = [0] * (n + 1)
        for i in range(n):
            pre[i + 1] = pre[i] + flowers[i]
        j = 0
        while j < n and flowers[n - 1 - j] >= target:
            j += 1
        ans = j * full
        cost = 0
        while True:
            m = n - j
            if m == 0:
                ans = max(ans, n * full)
                break
            rem = newFlowers - cost
            if rem < 0:
                break
            lo, hi = 0, target - 1
            while lo < hi:
                mid = (lo + hi + 1) // 2
                if mid * m - pre[m] <= rem:
                    lo = mid
                else:
                    hi = mid - 1
            ans = max(ans, j * full + lo * partial)
            if j < n:
                add = max(0, target - flowers[n - 1 - j])
                if cost + add <= newFlowers:
                    cost += add
                    j += 1
                else:
                    break
            else:
                break
        return ans

