            long long rem = newFlowers - cost;
            if (rem < 0) break;
            long long lo = 0, hi = target - 1;
            while (lo < hi) {
                long long mid = (lo + hi + 1) / 2;
                if (mid * (long long)m - pre[m] <= rem) lo = mid; else hi = mid - 1;
