var maximumBeauty = function(flowers, newFlowers, target, full, partial) {
    flowers.sort((a, b) => a - b);
    const n = flowers.length;
    const pre = Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) pre[i + 1] = pre[i] + flowers[i];
    let j = 0;
    while (j < n && flowers[n - 1 - j] >= target) j++;
    let ans = j * full, cost = 0;
    while (true) {
        const m = n - j;
        if (m === 0) { ans = Math.max(ans, n * full); break; }
        const rem = newFlowers - cost;
        if (rem < 0) break;
        let lo = 0, hi = target - 1;
        while (lo < hi) {
            const mid = Math.floor((lo + hi + 1) / 2);
            if (mid * m - pre[m] <= rem) lo = mid; else hi = mid - 1;
        }
        ans = Math.max(ans, j * full + lo * partial);
        if (j < n) {
            const add = Math.max(0, target - flowers[n - 1 - j]);
            if (cost + add <= newFlowers) { cost += add; j++; } else break;
        } else break;
    }
    return ans;
};
